/* Row layout: group, subgroup, label, credits, verbatim file text.
 *
 * The subgroup is the distinguishing axis, taken from the author's own
 * filename where they provided one (00 / LS for security, or the planet type)
 * and measured from the template where they did not (facility count). Without
 * it, 84 extractors were one undifferentiated wall and seven different
 * Bacteria miners read as the same entry repeated seven times. */
const IT_GROUP = 0, IT_SUB = 1, IT_NAME = 2, IT_CREDIT = 3, IT_TEXT = 4;

const TEMPLATE_SOURCES = {
  'DalShooth':     { label: "DalShooth's EVE PI Templates",
                     url: 'https://github.com/DalShooth/EVE_PI_Templates' },
  'TheLegi0n-NBI': { label: "The Legion's Playing With PP",
                     url: 'https://github.com/TheLegi0n-NBI/PlayingWithPP' },
  'josephdouce':   { label: "josephdouce's EVE PI Templates",
                     url: 'https://github.com/josephdouce/eve-pi-templates' },
  'Joakhan':       { label: "Joakhan's EVE PI Templates",
                     url: 'https://github.com/Joakhan/eve_pi_templates' },
  'Solving PI':    { label: 'Solving PI',
                     url: 'https://github.com/LackingTallent/SolvingPI' },
};

function importedGroups(){
  const seen = [];
  IMPORTED_TEMPLATES.forEach(r => {
    if (!seen.includes(r[IT_GROUP])) seen.push(r[IT_GROUP]);
  });
  return seen;
}
function importedSubgroups(group){
  const seen = [];
  IMPORTED_TEMPLATES.forEach(r => {
    if (r[IT_GROUP] === group && !seen.includes(r[IT_SUB])) seen.push(r[IT_SUB]);
  });
  return seen;
}
function importedIn(group, sub){
  return IMPORTED_TEMPLATES
    .filter(r => r[IT_GROUP] === group && (sub == null || r[IT_SUB] === sub))
    .map(r => ({ name: r[IT_NAME], credits: r[IT_CREDIT].split(','), text: r[IT_TEXT] }));
}
